from lib import *
S = SS('x98')
steps = [
    step("用同一个 MySQL 实例里的两个库 demo(当主库)和 replica(当从库)代替真正的主从,路由键是「当前事务是否 readOnly」。直接把 AbstractRoutingDataSource 的子类当 DataSource 用:@Transactional(readOnly = true) 的 readTx() 查到的库是 demo——没有走从库;determineCurrentLookupKey 只被调用 1 次,返回的是 primary。通常的解释是事务管理器在开启事务、拿连接的那一刻就调用了路由,此时 readOnly 标记还没设置到当前线程上,读到的是 false;我只验证了结果(用 LazyConnectionDataSourceProxy 之后就对了,见下一步)。@Transactional 的 writeTx() 和没有事务的 noTx() 同样在 demo。外层 readOnly 事务里调 REQUIRED 的写方法:抛 TransientDataAccessResourceException: Connection is read-only. Queries leading to data modification are not allowed(驱动在 readOnly 连接上拦住了写入)。外层 readOnly 调 REQUIRES_NEW 的写方法:新事务不是只读,写进了 demo,两个库的 log 表是 demo 里 2 行、replica 里 0 行。", t=tl(S(1)), mark=lidx(S(1), 'readTx()', '调 REQUIRED 的写方法'), done=lidx(S(1), 'writeTx()', 'noTx()', 'REQUIRES_NEW', '库 demo 的 log 表'), b=bars([['readOnly 事务实际路由到的库(1=replica)', 0, 'demo(没有走从库)'], ['determineCurrentLookupKey 的调用次数', 1, '1'], ['demo 库 log 表的行数', 2, '2'], ['replica 库 log 表的行数', 0, '0']], 2, mark=[0], done=[1, 2, 3]), kv=KV([['路由时机', '取连接时调用路由,当时 readOnly 标记读到 false(解释未单独验证)'], ['结果', 'readOnly 事务也走了主库'], ['REQUIRED 的写方法', '驱动拦住:Connection is read-only'], ['REQUIRES_NEW 的写方法', '新事务不是只读,写进主库']], ['路由时机'])),
    step("外面再包一层 LazyConnectionDataSourceProxy:DataSource 的类型变成 org.springframework.jdbc.datasource.LazyConnectionDataSourceProxy。readTx() 现在查到的库是 replica——代理推迟到第一条 SQL 才真正取连接,这时 readOnly 标记已经设置好;determineCurrentLookupKey 被调用了 2 次,依次返回 [primary, replica](第一次返回 primary,我没有追究它发生在什么时候;第二次才是 readOnly 的请求)。writeTx() 和 noTx() 仍然在 demo。外层 readOnly 调 REQUIRED 的写方法:路由到了 replica,写入同样被驱动的 read-only 拦截,抛 Connection is read-only;外层 readOnly 调 REQUIRES_NEW 的写方法:外层的读在 replica,内层的写在 demo(依次返回 [replica, primary]),demo 库 log 里是 writeTx 和那条 REQUIRES_NEW 的记录,replica 库 log 里没有东西。要点:路由依据的事务属性必须在取连接之前就绪,所以要加 LazyConnectionDataSourceProxy;真正的复制延迟(写完立刻读从库读不到)这里没有模拟。", t=tl(S(2)), mark=lidx(S(2), 'readTx()'), done=lidx(S(2), 'LazyConnectionDataSourceProxy', 'writeTx()', 'noTx()', 'REQUIRES_NEW'), b=bars([['readOnly 事务实际路由到的库(1=replica)', 1, 'replica'], ['determineCurrentLookupKey 的调用次数', 2, '2'], ['replica 库 log 表的行数', 0, '0'], ['demo 库 log 表的行数', 2, '2']], 2, mark=[0], done=[1, 2, 3]), kv=KV([['LazyConnectionDataSourceProxy', '推迟到第一条 SQL 才取连接,readOnly 标记已就绪'], ['readOnly 事务', '走 replica'], ['REQUIRES_NEW 的写方法', '走 primary'], ['未模拟', '主从复制延迟']], ['LazyConnectionDataSourceProxy'])),
]
A = mkartx('x98', 98, 'Spring,JDBC,读写分离,AbstractRoutingDataSource,事务,LazyConnectionDataSourceProxy,真实验证,动画演示',
    '实测 AbstractRoutingDataSource 做读写分离:直接用时 readOnly 事务也路由到了主库,因为取连接时 readOnly 标记还没设置;外面包一层 LazyConnectionDataSourceProxy 后 readOnly 事务才走从库;readOnly 外层里调 REQUIRED 的写方法被驱动拦住,调 REQUIRES_NEW 的写方法则走主库。',
    '读写分离用 AbstractRoutingDataSource 为什么经常不生效?readOnly 事务里写会怎样?内层 REQUIRES_NEW 走哪个库?这篇用同一个 MySQL 实例里的两个库代替主从,逐个实测。',
    [('走了主库', '直接用 AbstractRoutingDataSource,@Transactional(readOnly = true) 查询仍然落在主库'), ('replica', '外面包一层 LazyConnectionDataSourceProxy 之后,readOnly 事务才路由到从库'), ('Connection is read-only', 'readOnly 事务里 REQUIRED 的写方法被驱动拦住')],
    [('不生效的原因', '<p>路由在取连接时调用,而 readOnly 标记还没就绪,于是读到的是 false。</p>'),
     ('修复', '<p>外面包 LazyConnectionDataSourceProxy,推迟取连接;之后 readOnly 事务走从库,REQUIRES_NEW 的写方法走主库。</p>')],
    steps,
    [ENV_X + '(Spring Framework 7.0.9 的 AbstractRoutingDataSource 与 LazyConnectionDataSourceProxy;MySQL 是本机自己起的 26.7.0 实例,mysql-connector-j)。用同一个实例里的两个库 demo 与 replica 代替真正的主从,两个库之间没有复制;路由键取自 TransactionSynchronizationManager.isCurrentTransactionReadOnly();用 JdbcTemplate 而不是 JPA',
     '没有验证:真正的主从复制与复制延迟导致的读不到刚写入的数据;JPA / Hibernate 下 readOnly 事务的路由(HibernateJpaDialect 有自己设置连接 readOnly 的时机);用注解或 ThreadLocal 手动指定数据源的做法;从库故障时的降级;连接池按库分别配置的大小;分库分表中间件(如 ShardingSphere)的做法'],
    '读写分离')
